const byte relayPin = 7;
const byte relayOn = LOW; // bəzi modullar aktiv LOW, bəziləri HIGH

void setup() {
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, relayOn == LOW ? HIGH : LOW);
}

void loop() {
  digitalWrite(relayPin, relayOn);
  delay(1000);
  digitalWrite(relayPin, relayOn == LOW ? HIGH : LOW);
  delay(1000);
}
